const sun = new THREE.DirectionalLight(0xfff0d8, 2.6); sun.position.set(0.72, 0.677, -0.148); scene.add(sun);
scene.add(new THREE.HemisphereLight(0x6f86c8, 0x1a1420, 0.9));
