const _a = V3(), _b = V3(), _c = V3(), _d = V3(), X = V3(1, 0, 0), Y = V3(0, 1, 0), Z = V3(0, 0, 1), _qa = new THREE.Quaternion(), _qb = new THREE.Quaternion(), _m = new THREE.Matrix4(), _zero = V3();
